            <span style={{ flex: 1, paddingLeft: 8, fontSize: 12, color: "#a1a1aa" }}>Search files…</span>
            <Concentric.Inner as="span" style={{ padding: "6px 10px", background: "light-dark(#111, #f4f4f5)", color: "light-dark(#fff, #111)", fontSize: 11, fontWeight: 600 }}>
              Go
            </Concentric.Inner>
          </Concentric>
          <Concentric radius={Math.min(outer, 22)} gap={Math.min(gap, 6)} style={{ display: "flex", alignItems: "center", gap: 10, width: 156, background: "light-dark(#fff, #1c1c1f)", boxShadow: "0 0 0 1px light-dark(rgb(0 0 0 / 0.06), rgb(255 255 255 / 0.09))" }}>
            <Concentric.Inner style={{ display: "grid", placeItems: "center", width: 30, height: 30, background: "light-dark(#e8f7ee, #17301f)", color: "#1f9d55", fontSize: 14 }}>✓</Concentric.Inner>
            <span style={{ display: "grid", fontSize: 12, fontWeight: 600 }}>
              Saved
              <span style={{ fontSize: 10, fontWeight: 400, color: "light-dark(#71717a, #a1a1aa)" }}>All changes synced</span>
            </span>
          </Concentric>
        </div>
      </div>
      <div style={{ display: "grid", gap: 8, width: "100%" }}>
        {slider("Outer", outer, setOuter, 48)}
        {slider("Gap", gap, setGap, 24)}
        <span style={{ fontSize: 12, color: "light-dark(#71717a, #a1a1aa)" }}>Inner radius follows: {innerRadius(outer, gap)}px</span>
      </div>
    </div>
  );
}

